// Generated by scripts/build-lesson-bundles.cjs.
((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeMedvezhonokEdition = function (year, grade, rows, material = {}) {
  const letters = 'АБВГД';
  const plain = value => value.replace(/<\/?(?:em|strong|u)>/g, '');
  const escape = value => value.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(({author, question, choices, key, review, figure, unrated, points, acceptedAnswers}, index) => {
    const [title, idea, check] = review;
    const answer = letters.indexOf(key);
    if (acceptedAnswers && (!acceptedAnswers.includes(answer) || new Set(acceptedAnswers).size !== acceptedAnswers.length ||
        !acceptedAnswers.every(index => Number.isInteger(index) && index >= 0 && index < choices.length))) {
      throw new Error('Invalid accepted answers in ' + year + '/' + grade + '/' + (index + 1));
    }
    const textChoices = choices.map(plain);
    const options = figure?.options?.map(({src, detailSrc, description, pixelWidth, pixelHeight}, i) => ({
      image: src, ...(detailSrc ? {detailSrc} : {}), description, pixelWidth, pixelHeight, text: figure.onlyPictures ? '' : textChoices[i],
    })) ?? textChoices.map(text => ({text}));
    return {
      number: index + 1, title, author, question: plain(question), choices: textChoices,
      ...(plain(question) !== question ? {formattedQuestion: question} : {}),
      ...(textChoices.some((value,i) => value !== choices[i]) ? {formattedChoices: choices} : {}),
      ...(acceptedAnswers ? {acceptedAnswers} : {}),
      ...(unrated ? {questionNote: unrated, archiveAnswer: key} : {}),
      ...(figure ? {
        choiceLayout: {options, condition: figure.condition},
        choiceImages: options.map(option => option.image),
        ...(figure.condition ? {conditionImage: figure.condition.src, conditionAlt: figure.condition.alt} : {}),
      } : {}),
      answer: unrated ? null : answer, points: points ?? (index < 10 ? 3 : index < 20 ? 4 : 5),
      skill: 'Русский медвежонок · Языкознание', hideIntroText: true, showCompletedStep: true,
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ['Первый шаг', 'Рассуждение', idea],
        ['Проверка', 'Проверка', check],
        ['Ответ', unrated ? 'Ответ в архивном ключе' : 'Ответ', ''],
      ],
    };
  });
  const scenes = rows.map(({review, key}, i) => {
    const terms = review.slice(1).map(step => [...new Set(
      Array.from(step.matchAll(/«([^«»\n]{1,44})»/gu), match => match[1])
    )].slice(0, 5));
    return (step, frame) => {
      if (!step) return '';
      const tokens = step === 3 ? (lessons[i].acceptedAnswers ?? [letters.indexOf(key)]).map(index => {
        const result = lessons[i].choices[index].replace(/^\[(.*)\][.]?$/, '$1');
        return letters[index] + (result ? ' · ' + result : '');
      }) : terms[step-1];
      if (step < 3 && tokens.length < 2) return '';
      return '<div class="word-scene" data-result="' + (step === 3) + '">' + tokens.map((token, index) => {
        const reveal = Math.min(1, Math.max(0, (frame - index * 0.65) / 0.42));
        return '<span class="word-token" style="--reveal:' + reveal.toFixed(3) + '">' + escape(token) + '</span>';
      }).join('') + '</div>';
    };
  });
  const reviewedKey = rows.some(row => row.reviewedEdition);
  return {
    id: year + '-medvezhonok-' + grade, year, grades, subject: 'ru',
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы'),
    sources: {
      contest: 'Русский медвежонок',
      tasksUrl: 'assets/medvezhonok/' + year + '/' + (material.tasksFile ?? grade + '.pdf'),
      reviewedKey,
      answersUrl: 'assets/medvezhonok/' + year + '/' + (reviewedKey ? 'reviewed-' + grade + '.pdf' : material.answersFile ?? grade + '-answers.pdf'),
      ...(material.solutionsFile ? {solutionUrl: 'assets/medvezhonok/' + year + '/' + material.solutionsFile} : {}),
      ...(year === 2004 && grade === '2-3' ? {solutionUrl: 'assets/medvezhonok/2004/2-3-answers.pdf'} : {}),
    },
    lessons, scenes,
  };
};

register(globalThis.makeMedvezhonokEdition(2006, "2-3", [{"author":"Н. Валеева","question":"Существует такое шуточное правило: если в названии месяца есть буква <strong><em>р</em></strong> (например, <em>янва</em><strong><em>р</em></strong><em>ь</em>), то в этом месяце нельзя сидеть на голой земле, иначе простудишься. А сколько в году месяцев, когда по этому правилу на земле сидеть можно?","choices":["один","два","три","четыре","пять."],"key":"Г","review":["Месяцы без буквы р","Просмотри названия месяцев по порядку. После января, февраля, марта и апреля, где есть р, начинается ряд названий без этой буквы.","Это май, июнь, июль и август. С сентября по декабрь снова есть р, поэтому по шуточному правилу подходящих месяцев четыре."]},{"author":"Б. Иомдин","question":"Сегодня 16 ноября. Как сегодня называются дни 14 ноября и 18 ноября?","choices":["<em>повчера</em> и <em>позавтра</em>","<em>позавчера</em> и <em>послезавтра</em>","<em>послевчера</em> и <em>послезавтра</em>","<em>позавчера</em> и <em>позазавтра</em>","<em>послевчера</em> и <em>позазавтра.</em>"],"key":"Б","review":["Два дня в каждую сторону","От 16 ноября шагни на один день назад и вперёд. 15 ноября было вчера, а 17 ноября будет завтра.","Ещё один шаг назад даёт 14 ноября, то есть позавчера. Ещё один шаг вперёд даёт 18 ноября, то есть послезавтра."]},{"author":"Е. Муравенко","question":"Какое из этих слов станет бессмысленным, если его написать с маленькой буквы?","choices":["<em>Вера</em>","<em>Надежда</em>","<em>Любовь</em>","<em>Захар</em>","<em>Роман.</em>"],"key":"Г","review":["Имя с маленькой буквы","Прочитай «вера», «надежда», «любовь» и «роман» как обычные слова. Первые три называют чувства или отношение, а роман — литературное произведение.","«Захар» в этом списке — только имя. Его пишут с большой буквы, а обычного слова «захар» в русском языке нет."]},{"author":"Б. Иомдин","question":"Как правильно?","choices":["<em>скалить глаза, хмурить брови, щурить зубы</em>","<em>щурить глаза, скалить брови, хмурить зубы</em>","<em>хмурить глаза, щурить брови, скалить зубы</em>","<em>щурить глаза, хмурить брови, скалить зубы</em>","<em>хмурить глаза, скалить брови, щурить зубы</em>."],"key":"Г","review":["Глаза, брови и зубы","Представь три выражения лица. При ярком свете прикрывают глаза, при недовольстве сводят брови, а оскал показывает зубы.","Подходящие сочетания — «щурить глаза», «хмурить брови», «скалить зубы». Сравни со словами «прищур», «нахмуриться» и «оскал»."]},{"author":"Е. Муравенко","question":"В каком из слов на месте пропусков могут быть две одинаковые буквы?","choices":["<em>к_р_ва</em>","<em>ур_ж_й</em>","<em>к_рт_фель</em>","<em>с_б_ка</em>","<em>н_р_дный</em>."],"key":"А","review":["Две пропущенные буквы","Заполни пропуски и выпиши только вставленные буквы. В «урожай», «картофель» и «собака» пропущены о и а в разном порядке, а в «народный» — а и о.","В слове «корова» пропущены две о: к-о-р-о-ва. Проверь, что нужно сравнить именно два места пропуска."]},{"author":"О. Шеманаева и методкомиссия","question":"Какого языка не существует?","choices":["<em>немецкого</em>","<em>французского</em>","<em>турецкого</em>","<em>грецкого</em>","<em>итальянского</em>."],"key":"Г","review":["Названия языков","Сопоставь язык со страной. В Германии говорят по-немецки, во Франции — по-французски, в Турции — по-турецки, в Италии — по-итальянски.","Язык Греции называют греческим. Прилагательное «грецкий» употребляют, например, в названии ореха, поэтому «грецкого языка» в списке нет."]},{"author":"Л. Фёдорова","question":"Как в русских сказках обычно называют дочь царя?","choices":["<em>царь-девица</em>","<em>царица</em>","<em>царевна</em>","<em>королевна</em>","<em>принцесса</em>."],"key":"В","review":["Дочь царя в сказке","Различи слова «царица» и «царевна». Царица может сама править или быть женой царя. У слова с частью -евн- другая роль.","Дочь царя называется «царевна». Например, в сказке о спящей царевне так называют царскую дочь."]},{"author":"Б. Иомдин","question":"Даны названия частей слова из старого учебника правописания: <em>корень, представка, суффикс, окончание</em>. Какая из них теперь носит другое название?","choices":["<em>корень</em>","<em>представка</em>","<em>суффикс</em>","<em>окончание</em>","все части слова так и называются до сих пор."],"key":"Б","review":["Старые названия частей","Вспомни, какие части слова ты отмечаешь при разборе. «Корень», «суффикс» и «окончание» до сих пор называются так же.","Часть перед корнем теперь называют приставкой. В старом учебнике её называли «представка»."]},{"author":"Н. Валеева","question":"Усатый, полосатый, хвостатый — это:","choices":["таракан","арбуз","павлин","лев","тигр."],"key":"Д","review":["Усы, полосы и хвост","Проверь признаки отдельно. У арбуза есть полосы, у таракана заметны усы, у павлина — хвост, но нужно собрать все признаки у одного персонажа.","У льва есть усы и хвост, а у тигра вдобавок заметные полосы. Все три признака сходятся у тигра."]},{"author":"М. Кронгауз","question":"Девочку Людмилу могут звать Людой, Люсей или Милой, а вот Машей — вряд ли. А девочку Марию вряд ли будут называть …","choices":["Марфа","Маня","Маруся","Маша","Машенька."],"key":"А","review":["Как зовут Марию?","Сравни ласковые и короткие формы. «Маша» и «Машенька» связаны друг с другом, а «Маня» и «Маруся» тоже могут быть формами имени Мария.","Марфа — самостоятельное имя. Поэтому Марию вряд ли будут звать Марфой."]},{"author":"Е. Муравенко","question":"В каком из ребусов зашифрован символ нашего конкурса?","choices":["[МАРТЫШКА]","[КЕНГУРУ]","[МЕДВЕЖОНОК]","[ПОРОСЁНОК]","[КАНАРЕЙКА]."],"key":"В","review":["Символ конкурса в ребусе","В варианте В назови меч и число два. Запятая после рисунка убирает последнюю букву: «меч» даёт «ме», а «два» — «дв».","У ёжа зачёркнуты точки над ё, выходит «еж». Из «окно» в порядке 1, 3, 4, 2 получается «онок». Соедини «ме-дв-еж-онок»: это медвежонок, символ конкурса."],"figure":{"options":[{"src":"assets/medvezhonok/2006/2-3-11-1.svg","width":225,"height":104,"description":"Буква М, карты с запятой перед ними, шкаф с запятой после него"},{"src":"assets/medvezhonok/2006/2-3-11-2.svg","width":284,"height":118,"description":"Буквы Е и Н с руками и ногами стоят рядом. После гуся и после кисти руки по две запятые"},{"src":"assets/medvezhonok/2006/2-3-11-3.svg","width":312,"height":105,"description":"Меч и цифра 2, после каждого запятая. Над ежом зачёркнуты две точки, над окном цифры 1, 3, 4, 2"},{"src":"assets/medvezhonok/2006/2-3-11-4.svg","width":312,"height":114,"description":"Маленькие о на большой Р, Ё и Н рядом, затем запятая перед перевёрнутым котом"},{"src":"assets/medvezhonok/2006/2-3-11-5.svg","width":259,"height":128,"description":"Буквы КА над Р, затем лейка с запятой перед ней"}],"onlyPictures":true}},{"author":"Е. Муравенко","question":"Даны пары слов:\n1) <em>луг — лук</em>, 2) <em>балка — палка</em>, 3) <em>год — кот</em>, 4) <em>башня — басня</em>.\nВ каких парах произношение слов различается одним звуком?","choices":["во всех","во всех, кроме 3","во всех, кроме 1","только в 2, 3","только в 4."],"key":"В","review":["Буквы и звуки в парах","Произнеси «луг» и «лук»: конечная г в слове «луг» звучит как [к], поэтому пара произносится одинаково. В «год — кот» концы звучат одинаково, но первые звуки разные.","В «балка — палка» меняется первый звук, в «башня — басня» меняется [ш] на мягкий [с’]. Ровно один звук различается в парах 2, 3 и 4."]},{"author":"Е. Холодова","question":"Даны буквы <em>в</em>, <em>ж</em>, <em>л</em>, <em>м</em>, <em>с</em>. Какие из них можно вставить вместо пропуска перед буквосочетанием <strong><em>_ечь</em></strong>, чтобы получились правильные четырёхбуквенные русские слова?","choices":["все","<em>ж</em>, <em>л</em>, <em>м</em>, <em>с</em>","<em>в</em>, <em>л</em>, <em>м</em>","<em>ж</em>, <em>л</em>, <em>м</em>","<em>ж</em>, <em>л</em>, <em>с</em>."],"key":"Д","review":["Буква перед «ечь»","Подставь по одной букве в начало. Можно «жечь дрова», «лечь спать» и «сечь саблей» — это три настоящих глагола.","Проверка оставшихся: «вечь» и «мечь» в современной обычной речи не употребляются. Подходят буквы ж, л и с."]},{"author":"И. Иткин","question":"Торопясь доставить послание царю Салтану, гонец мчался ...","choices":["во весь топор","во весь упор","во весь опор","во весь отпор","во весь напор."],"key":"В","review":["Гонец спешит к царю","В пропуск нужно устойчивое выражение со значением «очень быстро». Найди привычное продолжение фразы «мчаться во весь…».","Говорят «во весь опор», когда несутся изо всех сил. Поэтому у гонца получается «мчался во весь опор»."]},{"author":"И. Рубанов","question":"Вот стихи поэта Эли Бар-Яалома:\n<em>Стоит рагу из овощей\nв тарелке предо мною,\nа рядом, средь других вещей,\nстоит рагу мясное.\nИ я на эти два рагу\nсмотрю, и видеть не могу!\nНет — я на этих двух рагов\nсмотрю, как на своих врагов!\nНет — я смотрю на две раги,\nкак на портрет Бабы-Яги!\nНет — я смотрю на два рага...\n...Ах, дайте лучше пирога,\nага?</em>\nТак как же всё-таки правильно?","choices":["<em>два рагу́</em>","<em>двух раго́в</em>","<em>две раги́</em>","<em>два рага́</em>","всё это неправильно."],"key":"А","review":["Две тарелки рагу","Попробуй сказать «нет рагу», «любуюсь рагу», «ем рагу». Само слово при этом остаётся одинаковым.","«Рагу» среднего рода и не склоняется, поэтому говорим «два рагу́». Можно для проверки развернуть сочетание: «два блюда с рагу»."]},{"author":"Е. Муравенко","question":"К четырём из пяти написанных ниже слов можно, не изменяя порядка букв, добавить в начало, конец или между какими-то двумя буквами букву <em>т</em> так, чтобы получилось новое слово. А из какого слова получить таким образом новое слово нельзя?","choices":["<em>сор</em>","<em>веер</em>","<em>пара</em>","<em>рубил</em>","<em>варил.</em>"],"key":"Д","review":["Добавь букву т","Поставь т в разные места, сохраняя прежние буквы. Из «сор», «веер», «пара» и «рубил» получаются «сорт», «ветер», «парта» и «трубил».","Перебери места для т в слове «варил». В отличие от остальных четырёх, общеупотребительного слова таким способом не выходит."]},{"author":"Е. Муравенко","question":"В какой из пар слова <strong>всегда</strong> обозначают разные предметы?","choices":["<em>зубок — зубик</em>","<em>годок — годик</em>","<em>листок — листик</em>","<em>лучок — лучик</em>","<em>часок — часик</em>."],"key":"Г","review":["Пять пар маленьких слов","«Зубок» и «зубик» могут называть один маленький зуб. Точно так же можно говорить об одном годе, листе и часе в парах «годок — годик», «листок — листик», «часок — часик».","«Лучик» — маленький луч света. «Лучок» — уменьшительное от слова «лук», например «зелёный лучок». Эти два слова обозначают разные вещи."]},{"author":"Е. Холодова","question":"<em>Его</em> не кажут, <em>им</em> клюют, с <em>ним</em> оставляют. О чём идёт речь?","choices":["о дневнике","о домашнем задании","о клюве","о носе","о кóрме."],"key":"Г","review":["Его не кажут","Проверь, к какой части тела подходит выражение «не казать …». Говорят «носа не казать», то есть не показываться.","Если человек засыпает сидя, он «клюёт носом». Если кого-то обманули, его «оставили с носом». Во всех трёх фразах говорится о носе."]},{"author":"Е. Вельмезова","question":"Какое из следующих слов противоположно по значению слову <em>смуглый</em>?","choices":["<em>белобрысый</em>","<em>белокожий</em>","<em>светловолосый</em>","<em>темноглазый</em>","<em>весёлый</em>."],"key":"Б","review":["Что значит «смуглый»?","Смуглым называют человека с тёмной кожей. Поэтому ищи противоположный признак кожи, а не цвет глаз или волос.","«Белокожий» значит «со светлой кожей». Так получается противоположность слову «смуглый»."]},{"author":"О. Шеманаева","question":"Кто из жителей Цветочного города назван не по тому же принципу, что остальные?","choices":["Пончик","Ворчун","Молчун","Торопыжка","Растеряйка."],"key":"А","review":["Имена в Цветочном городе","В имёнах Ворчун, Молчун, Торопыжка и Растеряйка спрятано поведение: ворчать, молчать, торопиться, растерять.","Пончик назван словом, которое обозначает выпечку. Его имя устроено иначе, чем имена от действий и привычек."]},{"author":"Б. Иомдин","question":"В каком из этих слов есть приставка?","choices":["<em>собственник</em>","<em>соплеменник</em>","<em>соусник</em>","<em>солист</em>","<em>сорняк</em>."],"key":"Б","review":["Где спряталась приставка?","Проверь, можно ли отнять «со-» и узнать основу с тем же смыслом. «Соплеменник» — человек из того же племени, а «со-» показывает общность, как в слове «соавтор».","В «собственник», «соусник», «солист» и «сорняк» начало принадлежит корню. Сравни «собственный», «соус», «соло» и «сорный»."]},{"author":"Б. Иомдин","question":"Илья Ильф пишет:\n<em>Смешную фразу надо лелеять, холить, ласково поглаживая по подлежащему.</em> А каково подлежащее этой фразы?","choices":["слово <em>фразу</em>","слово <em>надо</em>","слово <em>лелеять</em>","слово <em>подлежащему</em>","в этой фразе нет подлежащего."],"key":"Д","review":["Подлежащее у Ильфа","Найди основу фразы: «надо лелеять, холить». В ней говорится, что делать, но прямо не сказано, кто это делает.","«Фразу» отвечает на «что лелеять?», а «по подлежащему» зависит от «поглаживая». Значит, подлежащего в предложении нет."]},{"author":"И. Иткин","question":"Какое из этих слов обычно не употребляют, говоря о часах?","choices":["<em>лежат</em>","<em>стоят</em>","<em>идут</em>","<em>проходят</em>","<em>все эти слова нередко употребляют по отношению к часам.</em>"],"key":"Д","review":["Часы и время","Различи «часы» как предмет и «часы» как промежутки времени. Настольные часы могут стоять, наручные часы могут лежать на полке.","Исправные часы идут, а часы ожидания проходят. Всем четырём глаголам можно подобрать привычное предложение с часами."]},{"author":"Л. Фёдорова","question":"Что приносит сорока на хвосте?","choices":["осень","дожди","сказку","сплетню","письмо."],"key":"Г","review":["Сорока на хвосте","Вспомни, что говорят, когда хотят скрыть, откуда знают какую-то новость. «Сорока на хвосте принесла» — шутливое объяснение.","Так говорят об услышанной новости или слухе. Из пяти вариантов подходит «сплетню»."]},{"author":"И. Иткин и Д. Михеева","question":"Писатель Сергей Георгиев написал книгу рассказов о забавных вымышленных существах.\n1-ый рассказ называется «Бузявочка»;\n5-ый рассказ называется «Жузявочка»;\n11-ый рассказ называется «Пузявочка».\nСколько всего рассказов в книге?","choices":["13","20","24","30","33."],"key":"Б","review":["Порядок рассказов","Сравни первые буквы названий. Если перечислить согласные буквы алфавита и пропустить й, Б будет первой, Ж — пятой, а П — одиннадцатой.","Продолжи список до Щ, последней согласной буквы. Без й получается 20 букв, значит, по этому порядку в книге 20 рассказов."]},{"author":"Л. Фёдорова","question":"Во французском языке часто дают прозвища и шутливые наименования, составленные из двух слов. Вот три таких наименования, переведённые на русский язык дословно: храни-дурака, храни-платье, думай-дурак. Что они означают?","choices":["узелок на память, гардероб, перила","гардероб, узелок на память, перила","узелок на память, перила, гардероб","гардероб, перила, узелок на память","перила, гардероб, узелок на память."],"key":"Д","review":["Три шутливых названия","Подумай, что защищает даже невнимательного человека от падения и где хранят платье. Получаются перила и гардероб.","«Думай-дурак» напоминает о том, что надо не забыть. Это узелок на память. Порядок — перила, гардероб, узелок на память."]}]), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
